/* app.js -- the interactive demo.
 *
 * Everything numerical on this page comes from window.DEMO_* (generated by
 * experiments/make_demo_data.py from results/), except the pixels of the
 * fractal and of the "ground truth" panels, which are computed live by
 * fractal.js at the displayed resolution.
 */
(function () {
  "use strict";

  var F = window.Fractal;
  var D = {
    islands: window.DEMO_ISLANDS || null,
    cases: window.DEMO_CASES || null,
    stats: window.DEMO_STATS || null
  };
  var CAT = (D.islands && D.islands.catalogue) || [];
  var CAPS = ["w32", "w128", "w512"];
  var CAP_LABEL = { w32: "1.3k params", w128: "17k", w512: "266k" };
  var COLORS = { w32: "#95a5a6", w128: "#4c78ff", w512: "#e05a4a" };
  var INK = "#e6e9ef", MUTED = "#98a2b3", GRID = "#2a3242";

  var S = {
    view: { cx: 0, cy: 0, half: 1.5 },
    gridN: 300,
    selected: null,
    cap: "w512",
    zoomIdx: 4,
    population: "insample"
  };

  // ---------------------------------------------------------------- helpers
  function $(id) { return document.getElementById(id); }

  function num(v, d) {
    if (v === null || v === undefined || (typeof v === "number" && !isFinite(v))) {
      return "—";
    }
    return (typeof v === "number") ? v.toFixed(d === undefined ? 3 : d) : String(v);
  }

  function canvasSize(cv, maxPx) {
    var r = cv.getBoundingClientRect();
    var dpr = Math.min(window.devicePixelRatio || 1, 2);
    var w = Math.max(120, Math.round((r.width || 400) * dpr));
    w = Math.min(w, maxPx * dpr);
    if (cv.width !== w) { cv.width = w; cv.height = w; }
    return w;
  }

  function chartSize(cv) {
    var r = cv.getBoundingClientRect();
    var dpr = Math.min(window.devicePixelRatio || 1, 2);
    var w = Math.max(200, Math.round((r.width || 480) * dpr));
    var h = Math.max(160, Math.round((r.height || 260) * dpr));
    if (cv.width !== w || cv.height !== h) { cv.width = w; cv.height = h; }
    return { w: w, h: h, dpr: dpr };
  }

  function niceTicks(lo, hi, target) {
    if (!(hi > lo)) { return [lo]; }
    var raw = (hi - lo) / (target || 5);
    var mag = Math.pow(10, Math.floor(Math.log10(raw)));
    var norm = raw / mag;
    var step = (norm >= 5 ? 10 : norm >= 2 ? 5 : norm >= 1 ? 2 : 1) * mag;
    var out = [];
    for (var v = Math.ceil(lo / step) * step; v <= hi + 1e-9; v += step) {
      out.push(Math.abs(v) < 1e-12 ? 0 : v);
    }
    return out;
  }

  function logTicks(lo, hi) {
    var out = [];
    for (var e = Math.floor(Math.log10(lo)); e <= Math.ceil(Math.log10(hi)); e++) {
      var v = Math.pow(10, e);
      if (v >= lo * 0.999 && v <= hi * 1.001) { out.push(v); }
    }
    return out;
  }

  function tickLabel(v, isLog) {
    if (isLog) {
      return v >= 1000 ? (v / 1000).toFixed(0) + "k" : String(+v.toPrecision(3));
    }
    var a = Math.abs(v);
    if (a >= 1000) { return (v / 1000).toFixed(a >= 10000 ? 0 : 1) + "k"; }
    return String(+v.toPrecision(3));
  }

  // ---------------------------------------------------------------- charts
  /* Minimal canvas chart: linear or log axes, series with optional error bars,
     horizontal / vertical reference lines and annotations. */
  function drawChart(cv, opt) {
    var size = chartSize(cv);
    var ctx = cv.getContext("2d");
    var W = size.w, H = size.h, dpr = size.dpr;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, W, H);
    var pad = { l: 58 * dpr, r: 14 * dpr, t: 12 * dpr, b: 42 * dpr };
    var pw = W - pad.l - pad.r, ph = H - pad.t - pad.b;

    var series = (opt.series || []).filter(function (s) { return s.x && s.x.length; });
    var xs = [], ys = [];
    series.forEach(function (s) {
      s.x.forEach(function (v, i) {
        var y = s.y[i];
        if (isFinite(v) && isFinite(y)) { xs.push(v); ys.push(y); }
        if (s.err && isFinite(y) && isFinite(s.err[i])) {
          ys.push(y - s.err[i]); ys.push(y + s.err[i]);
        }
      });
    });
    (opt.hline || []).forEach(function (h) { ys.push(h.y); });
    if (!xs.length) { xs = [0, 1]; }
    if (!ys.length) { ys = [0, 1]; }

    var xlo = opt.xMin !== undefined ? opt.xMin : Math.min.apply(null, xs);
    var xhi = opt.xMax !== undefined ? opt.xMax : Math.max.apply(null, xs);
    var ylo = opt.yMin !== undefined ? opt.yMin : Math.min.apply(null, ys);
    var yhi = opt.yMax !== undefined ? opt.yMax : Math.max.apply(null, ys);
    if (opt.xLog) {
      xlo = opt.xMin !== undefined ? opt.xMin : xlo / 1.15;
      xhi = opt.xMax !== undefined ? opt.xMax : xhi * 1.15;
    } else {
      var xpad = (xhi - xlo) * 0.06 || 0.5;
      if (opt.xMin === undefined) { xlo -= xpad; }
      if (opt.xMax === undefined) { xhi += xpad; }
    }
    var ypad = (yhi - ylo) * 0.12 || 0.5;
    if (opt.yMin === undefined) { ylo -= ypad; }
    if (opt.yMax === undefined) { yhi += ypad; }

    function X(v) {
      var t = opt.xLog ? (Math.log(v) - Math.log(xlo)) /
                         (Math.log(xhi) - Math.log(xlo))
                       : (v - xlo) / (xhi - xlo);
      return pad.l + t * pw;
    }
    function Y(v) {
      var t = opt.yLog ? (Math.log(v) - Math.log(ylo)) /
                         (Math.log(yhi) - Math.log(ylo))
                       : (v - ylo) / (yhi - ylo);
      return pad.t + (1 - t) * ph;
    }

    // grid
    ctx.strokeStyle = GRID;
    ctx.lineWidth = 1;
    ctx.font = (11 * dpr) + "px ui-monospace, monospace";
    ctx.fillStyle = MUTED;
    var xt = opt.xTicks || (opt.xLog ? logTicks(xlo, xhi) : niceTicks(xlo, xhi, 5));
    var yt = opt.yTicks || (opt.yLog ? logTicks(ylo, yhi) : niceTicks(ylo, yhi, 4));
    xt.forEach(function (v) {
      var x = X(v);
      if (x < pad.l - 1 || x > W - pad.r + 1) { return; }
      ctx.beginPath(); ctx.moveTo(x, pad.t); ctx.lineTo(x, pad.t + ph); ctx.stroke();
      ctx.textAlign = "center"; ctx.textBaseline = "top";
      ctx.fillText(opt.xTickLabels ? (opt.xTickLabels[v] || tickLabel(v, opt.xLog))
                                   : tickLabel(v, opt.xLog),
                   x, pad.t + ph + 6 * dpr);
    });
    yt.forEach(function (v) {
      var y = Y(v);
      if (y < pad.t - 1 || y > pad.t + ph + 1) { return; }
      ctx.beginPath(); ctx.moveTo(pad.l, y); ctx.lineTo(pad.l + pw, y); ctx.stroke();
      ctx.textAlign = "right"; ctx.textBaseline = "middle";
      ctx.fillText(tickLabel(v, opt.yLog), pad.l - 8 * dpr, y);
    });

    // axis labels
    ctx.fillStyle = MUTED;
    ctx.textAlign = "center"; ctx.textBaseline = "bottom";
    if (opt.xLabel) { ctx.fillText(opt.xLabel, pad.l + pw / 2, H - 2 * dpr); }
    if (opt.yLabel) {
      ctx.save();
      ctx.translate(12 * dpr, pad.t + ph / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.textAlign = "center"; ctx.textBaseline = "top";
      ctx.fillText(opt.yLabel, 0, 0);
      ctx.restore();
    }

    // reference lines
    (opt.hline || []).forEach(function (h) {
      var y = Y(h.y);
      ctx.strokeStyle = h.color || MUTED;
      ctx.setLineDash((h.dash === false ? [] : [4 * dpr, 4 * dpr]));
      ctx.beginPath(); ctx.moveTo(pad.l, y); ctx.lineTo(pad.l + pw, y); ctx.stroke();
      ctx.setLineDash([]);
      if (h.label) {
        ctx.fillStyle = h.color || MUTED;
        ctx.textAlign = "left"; ctx.textBaseline = "bottom";
        ctx.fillText(h.label, pad.l + 6 * dpr, y - 2 * dpr);
      }
    });
    (opt.vline || []).forEach(function (v) {
      var x = X(v.x);
      ctx.strokeStyle = v.color || MUTED;
      ctx.setLineDash([3 * dpr, 3 * dpr]);
      ctx.lineWidth = 1.2;
      ctx.beginPath(); ctx.moveTo(x, pad.t); ctx.lineTo(x, pad.t + ph); ctx.stroke();
      ctx.setLineDash([]);
      ctx.lineWidth = 1;
    });

    // series
    series.forEach(function (s) {
      var pts = [];
      for (var i = 0; i < s.x.length; i++) {
        var v = s.x[i], y = s.y[i];
        if (!isFinite(v) || !isFinite(y)) { continue; }
        pts.push([X(v), Y(y), i]);
      }
      if (s.err) {
        ctx.strokeStyle = s.color;
        ctx.globalAlpha = 0.55;
        pts.forEach(function (p) {
          var y0 = Y(s.y[p[2]] - s.err[p[2]]), y1 = Y(s.y[p[2]] + s.err[p[2]]);
          if (!isFinite(y0) || !isFinite(y1)) { return; }
          ctx.beginPath();
          ctx.moveTo(p[0], y0); ctx.lineTo(p[0], y1);
          ctx.moveTo(p[0] - 3 * dpr, y0); ctx.lineTo(p[0] + 3 * dpr, y0);
          ctx.moveTo(p[0] - 3 * dpr, y1); ctx.lineTo(p[0] + 3 * dpr, y1);
          ctx.stroke();
        });
        ctx.globalAlpha = 1;
      }
      ctx.strokeStyle = s.color;
      ctx.lineWidth = (s.width || 1.6) * dpr;
      ctx.globalAlpha = s.alpha === undefined ? 1 : s.alpha;
      if (!s.noLine) {
        ctx.beginPath();
        pts.forEach(function (p, k) {
          if (k === 0) { ctx.moveTo(p[0], p[1]); } else { ctx.lineTo(p[0], p[1]); }
        });
        ctx.stroke();
      }
      ctx.fillStyle = s.color;
      pts.forEach(function (p) {
        if (s.markers === false) { return; }
        ctx.beginPath();
        ctx.arc(p[0], p[1], (s.ms || 3) * dpr, 0, 2 * Math.PI);
        ctx.fill();
      });
      ctx.globalAlpha = 1;
      ctx.lineWidth = 1;
    });

    // current-point markers
    (opt.marker || []).forEach(function (m) {
      var x = X(m.x), y = Y(m.y);
      ctx.strokeStyle = m.color || INK;
      ctx.lineWidth = 2 * dpr;
      ctx.beginPath();
      ctx.arc(x, y, 7 * dpr, 0, 2 * Math.PI);
      ctx.stroke();
      ctx.lineWidth = 1;
    });

    // annotations
    (opt.annotate || []).forEach(function (a) {
      ctx.fillStyle = a.color || INK;
      ctx.font = (a.size || 12) * dpr + "px ui-monospace, monospace";
      ctx.textAlign = a.align || "left";
      ctx.textBaseline = "top";
      ctx.fillText(a.text, X(a.x), Y(a.y));
    });
  }

  function legend(node, items) {
    node.innerHTML = items.map(function (it) {
      return '<span><i style="background:' + it.color + '"></i>' + it.label +
             "</span>";
    }).join("");
  }

  // ---------------------------------------------------------------- tab 1
  var dotsCanvas = document.createElement("canvas");
  var dotsCtx = dotsCanvas.getContext("2d");

  function renderSystem() {
    var cv = $("fractal");
    var n = Math.min(canvasSize(cv, 760), 720);
    var ctx = cv.getContext("2d");
    var view = S.view;
    var out = F.raster(n, view);
    var img = ctx.createImageData(n, n);
    F.fillImage(img, n, out);
    ctx.putImageData(img, 0, 0);

    // sampling grid, as an overlay image so that large n stays cheap
    if (dotsCanvas.width !== n) { dotsCanvas.width = n; dotsCanvas.height = n; }
    var dimg = dotsCtx.createImageData(n, n);
    var d = dimg.data;
    var half = view.half, step = (2 * half) / (n - 1);
    var gn = S.gridN;
    var h = 3 / (gn - 1);
    var i0 = Math.max(0, Math.floor((view.cx - half + 1.5) / h));
    var i1 = Math.min(gn - 1, Math.ceil((view.cx + half + 1.5) / h));
    var j0 = Math.max(0, Math.floor((view.cy - half + 1.5) / h));
    var j1 = Math.min(gn - 1, Math.ceil((view.cy + half + 1.5) / h));
    for (var j = j0; j <= j1; j++) {
      var y = -1.5 + j * h;
      var py = Math.round((view.cy + half - y) / step - 0.5);
      if (py < 0 || py >= n) { continue; }
      for (var i = i0; i <= i1; i++) {
        var x = -1.5 + i * h;
        var pxl = Math.round((x - (view.cx - half)) / step - 0.5);
        if (pxl < 0 || pxl >= n) { continue; }
        var q = 4 * (py * n + pxl);
        d[q] = 255; d[q + 1] = 255; d[q + 2] = 255; d[q + 3] = 170;
      }
    }
    dotsCtx.putImageData(dimg, 0, 0);
    ctx.globalAlpha = 0.55;
    ctx.drawImage(dotsCanvas, 0, 0);
    ctx.globalAlpha = 1;

    // islands
    var scale = n / (2 * half);
    CAT.forEach(function (isl) {
      var cx = (isl.cx - view.cx) * scale + n / 2;
      var cy = (view.cy - isl.cy) * scale + n / 2;
      var r = Math.max(2.2 * (n / 720), isl.width_units * scale * 0.5);
      if (cx < -20 || cy < -20 || cx > n + 20 || cy > n + 20) { return; }
      ctx.beginPath();
      ctx.arc(cx, cy, r, 0, 2 * Math.PI);
      ctx.fillStyle = "rgba(255,255,255,0.92)";
      ctx.fill();
      ctx.strokeStyle = "rgba(0,0,0,0.55)";
      ctx.lineWidth = 1;
      ctx.stroke();
      if (S.selected && S.selected.id === isl.id) {
        ctx.beginPath();
        ctx.arc(cx, cy, r + 5, 0, 2 * Math.PI);
        ctx.strokeStyle = "#4c78ff";
        ctx.lineWidth = 2;
        ctx.stroke();
      }
    });

    // readout
    var hits = F.gridHits(CAT, gn, D.islands.cell, 1.5);
    var isl = S.selected || CAT[0];
    var hh = 3 / (gn - 1);
    var rows = [
      ["training points", gn + " × " + gn + " = " + (gn * gn).toLocaleString()],
      ["grid spacing h", num(hh, 4) + " units"],
      ["islands hit by ≥1 point", hits.hits + " / " + hits.total],
      ["island width w", num(isl.width_units, 4) + " units"],
      ["w / h", num(isl.width_units / hh, 2) + " samples across"],
      ["island area", isl.area + " fine cells (" +
        num(100 * isl.area / (D.islands.n_fine * D.islands.n_fine), 5) + " %)"]
    ];
    $("system-readout").innerHTML = rows.map(function (r, k) {
      var cls = k === 2 ? (hits.hits > 0 ? "good" : "hot") : "";
      return "<dt>" + r[0] + "</dt><dd class='" + cls + "'>" + r[1] + "</dd>";
    }).join("");

    var note = $("system-note");
    if (hits.hits === 0) {
      note.className = "callout warn";
      note.innerHTML = "<b>No island is sampled at all.</b> At this grid the " +
        "acquisition step cannot propose a single island point: its support is " +
        "the training grid, so the islands are unreachable regardless of entropy.";
    } else {
      note.className = "callout";
      note.innerHTML = "<b>" + hits.hits + " of " + hits.total +
        " islands contain at least one training point.</b> The other " +
        (hits.total - hits.hits) + " can never be proposed by an acquisition " +
        "rule that samples around existing training points — no matter how high " +
        "their entropy is.";
    }
    S.hits = hits;
  }

  function zoomTo(x, y, half) {
    S.view = { cx: x, cy: y, half: half };
    renderSystem();
  }

  // ---------------------------------------------------------------- tab 2
  function caseFor(cap, zoom) {
    var cs = (D.cases && D.cases.cases) || [];
    for (var k = 0; k < cs.length; k++) {
      if (cs[k].cap === cap && Math.abs(cs[k].zoom - zoom) < 1e-9) { return cs[k]; }
    }
    return null;
  }

  function currentCase() {
    var z = D.cases ? D.cases.zooms[S.zoomIdx] : 4;
    return { c: caseFor(S.cap, z), zoom: z };
  }

  function renderResolution() {
    if (!D.cases) { return; }
    var cur = currentCase();
    var c = cur.c;
    if (!c) { return; }
    var isl = D.cases.island;
    var half = 0.5 * isl.width_units * cur.zoom;
    var view = { cx: isl.cx, cy: isl.cy, half: half };

    // truth
    var tv = $("truth");
    var tn = canvasSize(tv, 520);
    var tctx = tv.getContext("2d");
    var out = F.raster(tn, view);
    var img = tctx.createImageData(tn, tn);
    F.fillImage(img, tn, out);
    tctx.putImageData(img, 0, 0);

    // prediction (PNG is stored with row 0 at the BOTTOM of the window)
    var pv = $("pred");
    var pn = canvasSize(pv, 520);
    var pctx = pv.getContext("2d");
    var img2 = new Image();
    img2.onload = function () {
      pctx.save();
      pctx.translate(0, pn);
      pctx.scale(1, -1);
      pctx.imageSmoothingEnabled = false;
      pctx.drawImage(img2, 0, 0, pn, pn);
      pctx.restore();
      if (c) { drawIslandBox(pctx, pn, view, isl); }
    };
    img2.src = "fields/" + c.field;

    drawIslandBox(tctx, tn, view, isl);

    // readout
    var rows = [
      ["window", num(c.window_units, 4) + " units wide"],
      ["island width", num(c.w_units, 4) + " units"],
      ["samples across", num(c.cells, 1) + " (199 / k)"],
      ["recovered", num(c.recover, 2)],
      ["frozen into neighbour", num(c.freeze, 2)],
      ["accuracy away from island", c.acc_far === null ? "—" : num(c.acc_far, 3)]
    ];
    $("res-readout").innerHTML = rows.map(function (r, k) {
      var cls = k === 4 ? (c.freeze > 0.4 ? "hot" : "") :
                k === 3 ? (c.recover > 0.5 ? "good" : "hot") : "";
      return "<dt>" + r[0] + "</dt><dd class='" + cls + "'>" + r[1] + "</dd>";
    }).join("");

    var note = $("res-note");
    if (c.recover > 0.5) {
      note.className = "callout";
      note.innerHTML = "<b>The island is resolved.</b> It spans " +
        num(c.cells, 1) + " training cells, well above the ~2–3 measured " +
        "threshold for this capacity.";
    } else {
      note.className = "callout warn";
      note.innerHTML = "<b>The island is frozen into its neighbour</b> while " +
        "every aggregate number stays at " + num(c.acc_far, 2) +
        ". The same model, on the same data, is right about everything except " +
        "the feature that matters.";
    }
    $("zoom-label").textContent = "k = " + cur.zoom + "  (island spans " +
      num(c.cells, 1) + " cells)";

    // per-capacity series with the current point marked
    var series = CAPS.map(function (cap) {
      var rows = (D.cases.cases || []).filter(function (r) { return r.cap === cap; });
      rows.sort(function (a, b) { return a.cells - b.cells; });
      return {
        name: CAP_LABEL[cap], color: COLORS[cap],
        x: rows.map(function (r) { return r.cells; }),
        y: rows.map(function (r) { return r.recover; }),
        alpha: cap === S.cap ? 1 : 0.45
      };
    });
    drawChart($("chart-zoom"), {
      xLog: true, yMin: -0.05, yMax: 1.05,
      xLabel: "island width / sampling spacing (cells)",
      yLabel: "recovery",
      series: series,
      hline: [{ y: 0.5, dash: false, color: "#6b7488" }],
      marker: [{ x: c.cells, y: c.recover, color: INK }]
    });
    legend($("legend-zoom"), CAPS.map(function (cap) {
      return { color: COLORS[cap], label: cap + " (" + CAP_LABEL[cap] + ")" };
    }));
  }

  function drawIslandBox(ctx, n, view, isl) {
    var y0 = isl.origin[0], x0 = isl.origin[1];
    var cell = D.islands.cell;
    var scale = n / (2 * view.half);
    var x = (function (px) { return (-1.5 + px * cell - view.cx) * scale + n / 2; });
    var y = (function (py) { return (view.cy - (-1.5 + py * cell)) * scale + n / 2; });
    ctx.save();
    ctx.fillStyle = "rgba(255,255,255,0.28)";
    ctx.strokeStyle = "rgba(255,255,255,0.95)";
    ctx.lineWidth = 1.2;
    for (var r = 0; r < isl.mask.length; r++) {
      for (var c = 0; c < isl.mask[r].length; c++) {
        if (isl.mask[r].charCodeAt(c) !== 49) { continue; }
        var px = x0 + c, py = y0 + r;
        var s = cell * scale;
        ctx.fillRect(x(px) - s / 2, y(py + 0.5) - s / 2, s, s);
        ctx.strokeRect(x(px) - s / 2, y(py + 0.5) - s / 2, s, s);
      }
    }
    ctx.restore();
  }

  // ---------------------------------------------------------------- tab 3
  function renderEvidence() {
    if (!D.stats) { return; }
    var ph = D.stats.island_phase;

    // (a) island recovery vs w/h with CIs and the w_c markers
    var series = [], vlines = [];
    CAPS.forEach(function (cap) {
      var e = ph && ph[cap];
      if (!e) { return; }
      series.push({ name: cap, color: COLORS[cap], x: e.x, y: e.mean, err: e.std });
      if (e.wc) { vlines.push({ x: e.wc, color: COLORS[cap] }); }
    });
    drawChart($("chart-island"), {
      xLog: true, yMin: -0.05, yMax: 1.05,
      xLabel: "w / h  (samples across the island)",
      yLabel: "recovery",
      series: series, vline: vlines,
      hline: [{ y: 0.5, dash: false, color: "#6b7488" }]
    });
    legend($("legend-island"), CAPS.map(function (cap) {
      var e = ph && ph[cap];
      return {
        color: COLORS[cap],
        label: cap + (e && e.wc ? "  w_c = " + e.wc :
          "  (" + CAP_LABEL[cap] + ")")
      };
    }));

    // (b) w_c vs parameters
    var pts = { x: [], y: [] };
    CAPS.forEach(function (cap) {
      var e = ph && ph[cap];
      if (e && e.wc) { pts.x.push(e.params); pts.y.push(e.wc); }
    });
    var slope = -0.053, icpt = 4.58;
    var fit = { x: [], y: [] };
    if (pts.x.length > 1) {
      var lo = Math.min.apply(null, pts.x) / 1.5, hi = Math.max.apply(null, pts.x) * 1.5;
      for (var k = 0; k <= 20; k++) {
        var p = lo * Math.pow(hi / lo, k / 20);
        fit.x.push(p); fit.y.push(icpt * Math.pow(p, slope));
      }
    }
    drawChart($("chart-wc"), {
      xLog: true, yLog: true,
      xLabel: "MLP parameters", yLabel: "w_c (samples across)",
      series: [
        { name: "w_c", color: "#e0b000", x: pts.x, y: pts.y, noLine: true, ms: 4 },
        { name: "fit", color: "#6b7488", x: fit.x, y: fit.y, markers: false }
      ],
      annotate: [{ x: pts.x.length ? Math.min.apply(null, pts.x) : 1000,
                   y: 5.2, text: "w_c ~ params^−0.053", color: "#e0b000" }]
    });

    // (c) peninsula thickness
    var th = D.stats.peninsula_thin, rowsT = [], rowsT2 = [];
    var lseries = [];
    CAPS.forEach(function (cap) {
      var e = th && th[cap];
      if (!e) { return; }
      lseries.push({ name: cap, color: COLORS[cap], x: e.x, y: e.mean, err: e.std });
    });
    drawChart($("chart-pen"), {
      xLog: true, yMin: 0, yMax: 1.02,
      xLabel: "corridor thickness t (plane units)",
      yLabel: "recovery",
      series: lseries,
      hline: [{ y: 1 / 3, label: "chance", color: "#6b7488" }]
    });
    legend($("legend-pen"), CAPS.map(function (cap) {
      return { color: COLORS[cap], label: cap + " (" + CAP_LABEL[cap] + ")" };
    }));

    // (d) root -> tip
    var ge = D.stats.peninsula_geo, gseries = [];
    CAPS.forEach(function (cap) {
      var e = ge && ge[cap];
      if (!e) { return; }
      gseries.push({ name: cap, color: COLORS[cap], x: e.bins, y: e.mean, err: e.std });
    });
    drawChart($("chart-root"), {
      yMin: 0, yMax: 1.02,
      xLabel: "distance from the thick core (bin: 1 = root)",
      yLabel: "recovery",
      series: gseries,
      hline: [{ y: 1 / 3, label: "chance", color: "#6b7488" }]
    });
    legend($("legend-root"), CAPS.map(function (cap) {
      return { color: COLORS[cap], label: cap };
    }));

    // protocol table
    var p = D.stats.protocol;
    var t = $("table-protocol");
    if (p) {
      var rows = [
        ["islands in the catalogue", p.n_islands + "  (" + p.n_buried + " buried)"],
        ["island area", num(p.island_area_pct, 4) + " % of the plane"],
        ["training points (200 × 200)", p.n_train.toLocaleString()],
        ["training points on an island", p.train_points_in_islands + " of " +
          p.n_train.toLocaleString()],
        ["islands touched by the grid", p.train_islands_touched + " of " +
          p.n_islands],
        ["evaluation points (400 × 400)", p.n_eval.toLocaleString()],
        ["top 10 % by entropy (the “separatrix”)", p.n_selected.toLocaleString()],
        ["… of which on an island", p.selected_in_islands + "  (" +
          num(100 * p.selected_in_islands / p.n_selected, 3) + " %)"],
        ["islands with ≥1 selected point", p.islands_with_selected + " of " +
          p.n_islands],
        ["island cells the classifier gets right", p.island_cells_recovered +
          " of " + p.island_cells_evaluated + "  (" +
          num(p.island_recovery_pct, 1) + " %)"]
      ];
      t.innerHTML = "<tr><th>quantity</th><th class='num'>value</th></tr>" +
        rows.map(function (r) {
          return "<tr><td>" + r[0] + "</td><td class='num'>" + r[1] + "</td></tr>";
        }).join("");
    }
  }

  // ---------------------------------------------------------------- tab 4
  function renderTrap() {
    var mt = D.stats && D.stats.metric_trap;
    if (!mt || !mt.refinement) { return; }
    var r = mt.refinement;
    var insample = S.population === "insample";
    var series = [
      { name: "in-sample (training set)", color: "#8e44ad",
        x: r.rounds, y: r.in_sample_boundary_acc,
        alpha: insample ? 1 : 0.35, width: insample ? 2.4 : 1.4 },
      { name: "fixed population (band 1)", color: "#16a085",
        x: r.rounds, y: r.band1,
        alpha: insample ? 0.35 : 1, width: insample ? 1.4 : 2.4 }
    ];
    drawChart($("chart-trap"), {
      xMin: 0.8, xMax: 5.2, yMin: 0.3, yMax: 1.0,
      xLabel: "refinement round", yLabel: "separatrix accuracy",
      xTicks: [1, 2, 3, 4, 5],
      series: series
    });
    legend($("legend-trap"), [
      { color: "#8e44ad", label: "in-sample (population shifts)" },
      { color: "#16a085", label: "fixed independent population" }
    ]);

    var d_in = r.in_sample_boundary_acc[4] - r.in_sample_boundary_acc[0];
    var d_fix = r.band1[4] - r.band1[0];
    var rows = [
      ["boundary share of the training set",
        r.boundary_fraction[0].toFixed(0) + " % → " +
        r.boundary_fraction[4].toFixed(0) + " %"],
      ["in-sample separatrix accuracy", num(r.in_sample_boundary_acc[0], 3) +
        " → " + num(r.in_sample_boundary_acc[4], 3) + "  (" +
        (d_in >= 0 ? "+" : "") + num(d_in, 3) + ")"],
      ["fixed-population band-1 accuracy", num(r.band1[0], 3) + " → " +
        num(r.band1[4], 3) + "  (" + (d_fix >= 0 ? "+" : "") + num(d_fix, 3) + ")"],
      ["calibration error inside band 1", num(r.ece_band1[0], 3) + " → " +
        num(r.ece_band1[4], 3)]
    ];
    $("trap-readout").innerHTML = rows.map(function (x, k) {
      var cls = k === 1 ? "hot" : k === 2 ? "good" : "";
      return "<dt>" + x[0] + "</dt><dd class='" + cls + "'>" + x[1] + "</dd>";
    }).join("");

    var note = $("trap-note");
    note.className = insample ? "callout warn" : "callout";
    note.innerHTML = insample
      ? "<b>Read the greyed curve:</b> on a fixed population the same models " +
        "get <em>better</em>. The decline you see in blue is the metric's " +
        "population moving towards the hard band, not the model degrading."
      : "<b>This is the number to trust.</b> The band-1 accuracy rises and the " +
        "calibration error inside the band falls; nothing " +
        "“collapses” — the apparent collapse is a population artefact.";
  }

  // ---------------------------------------------------------------- wiring
  function activate(tab) {
    ["system", "resolution", "evidence", "trap"].forEach(function (t) {
      var on = t === tab;
      $("tab-" + t).classList.toggle("active", on);
      var btn = document.querySelector('nav.tabs button[data-tab="' + t + '"]');
      if (btn) { btn.classList.toggle("active", on); }
    });
    if (tab === "system") { renderSystem(); }
    if (tab === "resolution") { renderResolution(); }
    if (tab === "evidence") { renderEvidence(); }
    if (tab === "trap") { renderTrap(); }
    try {
      if (history.replaceState) { history.replaceState(null, "", "#" + tab); }
    } catch (e) { /* file:// in some browsers forbids it; harmless */ }
  }

  function init() {
    if (!D.islands || !D.cases || !D.stats) {
      document.body.insertAdjacentHTML("afterbegin",
        '<div style="padding:24px;font:14px monospace;color:#e05a4a">' +
        "Demo data is missing. Run <b>python experiments/make_demo_data.py</b> " +
        "to generate docs/data/*.js and docs/fields/*.png.</div>");
      return;
    }

    // tabs
    document.querySelectorAll("nav.tabs button").forEach(function (b) {
      b.addEventListener("click", function () { activate(b.dataset.tab); });
    });

    // grid slider
    var gn = $("grid-n");
    gn.addEventListener("input", function () {
      S.gridN = parseInt(gn.value, 10);
      $("grid-n-label").textContent =
        S.gridN.toLocaleString() + " × " + S.gridN.toLocaleString();
      if ($("tab-system").classList.contains("active")) { renderSystem(); }
    });
    $("grid-n-label").textContent =
      S.gridN.toLocaleString() + " × " + S.gridN.toLocaleString();

    // view interaction
    var cv = $("fractal");
    var drag = null;
    cv.addEventListener("wheel", function (ev) {
      ev.preventDefault();
      var rect = cv.getBoundingClientRect();
      var mx = (ev.clientX - rect.left) / rect.width;
      var my = (ev.clientY - rect.top) / rect.height;
      var v = S.view;
      var wx = v.cx - v.half + 2 * v.half * mx;
      var wy = v.cy + v.half - 2 * v.half * my;
      var factor = ev.deltaY > 0 ? 1.18 : 1 / 1.18;
      var half = Math.min(3.0, Math.max(2e-5, v.half * factor));
      var sx = (wx - (v.cx - v.half)) / (2 * v.half);
      var sy = ((v.cy + v.half) - wy) / (2 * v.half);
      S.view = {
        cx: wx + (0.5 - sx) * 2 * half,
        cy: wy - (0.5 - sy) * 2 * half,
        half: half
      };
      renderSystem();
    }, { passive: false });

    cv.addEventListener("pointerdown", function (ev) {
      drag = { x: ev.clientX, y: ev.clientY, view: S.view, moved: false };
      cv.classList.add("dragging");
      cv.setPointerCapture(ev.pointerId);
    });
    cv.addEventListener("pointermove", function (ev) {
      if (!drag) { return; }
      var rect = cv.getBoundingClientRect();
      var dx = (ev.clientX - drag.x) / rect.width;
      var dy = (ev.clientY - drag.y) / rect.height;
      if (Math.abs(dx) + Math.abs(dy) > 0.004) { drag.moved = true; }
      S.view = {
        cx: drag.view.cx - dx * 2 * drag.view.half,
        cy: drag.view.cy + dy * 2 * drag.view.half,
        half: drag.view.half
      };
      renderSystem();
    });
    cv.addEventListener("pointerup", function (ev) {
      cv.classList.remove("dragging");
      if (drag && !drag.moved) {
        var rect = cv.getBoundingClientRect();
        var mx = (ev.clientX - rect.left) / rect.width;
        var my = (ev.clientY - rect.top) / rect.height;
        var x = S.view.cx - S.view.half + 2 * S.view.half * mx;
        var y = S.view.cy + S.view.half - 2 * S.view.half * my;
        var isl = F.islandAt(CAT, x, y);
        if (isl) { S.selected = isl; renderSystem(); }
      }
      drag = null;
    });
    cv.addEventListener("pointerleave", function () {
      cv.classList.remove("dragging"); drag = null;
    });

    $("btn-reset").addEventListener("click", function () {
      zoomTo(0, 0, 1.5);
    });
    $("btn-island").addEventListener("click", function () {
      var isl = CAT[0];
      S.selected = isl;
      zoomTo(isl.cx, isl.cy, Math.max(6 * isl.width_units, 2e-3));
    });

    // capacity buttons
    var cb = $("cap-buttons");
    CAPS.forEach(function (cap) {
      var b = document.createElement("button");
      b.className = "pill" + (cap === S.cap ? " active" : "");
      b.textContent = CAP_LABEL[cap];
      b.addEventListener("click", function () {
        S.cap = cap;
        Array.prototype.forEach.call(cb.children, function (o) {
          o.classList.toggle("active", o.textContent === CAP_LABEL[cap]);
        });
        renderResolution();
      });
      cb.appendChild(b);
    });

    var zs = $("zoom");
    zs.max = String(D.cases ? D.cases.zooms.length - 1 : 5);
    zs.value = String(S.zoomIdx);
    zs.addEventListener("input", function () {
      S.zoomIdx = parseInt(zs.value, 10);
      renderResolution();
    });

    // population toggle
    var pb = $("pop-buttons");
    [["insample", "in-sample (training set)"],
     ["fixed", "fixed population"]].forEach(function (pair) {
      var b = document.createElement("button");
      b.className = "pill" + (pair[0] === S.population ? " active" : "");
      b.textContent = pair[1];
      b.addEventListener("click", function () {
        S.population = pair[0];
        Array.prototype.forEach.call(pb.children, function (o) {
          o.classList.toggle("active", o.textContent === pair[1]);
        });
        renderTrap();
      });
      pb.appendChild(b);
    });

    // resize
    var timer = null;
    window.addEventListener("resize", function () {
      clearTimeout(timer);
      timer = setTimeout(function () {
        var active = document.querySelector("section.tab.active");
        if (active) { activate(active.id.replace("tab-", "")); }
      }, 180);
    });

    var start = (location.hash || "#system").slice(1);
    if (["system", "resolution", "evidence", "trap"].indexOf(start) < 0) {
      start = "system";
    }
    activate(start);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
